30	    @Mapping(target = "initials",
31	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
32	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
33	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
34	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
35	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
36	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
37	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
38	    @Mapping(target = "locality", expression = "java(locality(owner))")
39	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
40	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
41	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
42	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
43	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
44	    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    /**
48	     * Known disposable email service names, matched as a whole dot-separated label anywhere in an
49	     * owner's email domain to detect a domain that is <em>disposable-adjacent</em>. These are the base
50	     * labels of the disposable domains rejected outright at creation ({@code mailinator.com},
51	     * {@code tempmail.com}, {@code guerrillamail.com}); a domain that carries one of these labels but
52	     * is not itself on the exact blocklist (a subdomain such as {@code mail.mailinator.com} or a
53	     * different TLD such as {@code tempmail.net}) evaded the blocklist yet is still risky.
54	     */
55	    java.util.Set<String> DISPOSABLE_ADJACENT_LABELS = java.util.Set.of(
56	        "mailinator", "tempmail", "guerrillamail");
57	
58	    /**
59	     * Derives an owner's risk flag: {@code true} when any of the following hold, otherwise
60	     * {@code false}. The owner is a possible duplicate ({@link Owner#getPossibleDuplicate()}), the
61	     * owner's email domain is {@link #disposableAdjacentEmail(Owner) disposable-adjacent}, or the
62	     * owner's city was over its soft capacity when created ({@link Owner#getCapacityWarning()}).
63	     *
64	     * @param owner the owner to derive the risk flag for
65	     * @return {@code true} when the owner is a possible duplicate, has a disposable-adjacent email
66	     *     domain, or was created over its city's soft capacity; otherwise {@code false}
67	     */
68	    default Boolean riskFlag(Owner owner) {
69	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
70	            || Boolean.TRUE.equals(owner.getCapacityWarning())
71	            || disposableAdjacentEmail(owner);
72	    }
73	
74	    /**
75	     * Determines whether an owner's email domain is <em>disposable-adjacent</em>: any of the domain's
76	     * dot-separated labels (compared case-insensitively) matches a known disposable email service name
77	     * ({@link #DISPOSABLE_ADJACENT_LABELS}). This catches domains that evade the exact disposable
78	     * blocklist enforced at creation, such as a subdomain ({@code mail.mailinator.com}) or a variant
79	     * TLD ({@code tempmail.net}). An owner with no email, or a value without a domain part, is not
80	     * disposable-adjacent.
81	     *
82	     * @param owner the owner whose email domain is examined
83	     * @return {@code true} when the email domain carries a known disposable-service label, otherwise
84	     *     {@code false}
85	     */
86	    default boolean disposableAdjacentEmail(Owner owner) {
87	        String email = owner.getEmail();
88	        if (email == null || email.isBlank()) {
89	            return false;
90	        }
91	        int at = email.lastIndexOf('@');
92	        if (at < 0 || at == email.length() - 1) {
93	            return false;
94	        }
95	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
96	        for (String label : domain.split("\\.")) {
97	            if (DISPOSABLE_ADJACENT_LABELS.contains(label)) {
98	                return true;
99	            }
100	        }
101	        return false;
102	    }
103	
104	    /**
105	     * Derives a link to the owner's own resource, formatted {@code /api/owners/<id>} where
106	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet, so the
107	     * field is omitted from the response.
108	     *
109	     * @param owner the owner to derive the self link for
110	     * @return the {@code /api/owners/<id>} self link, or {@code null} when the owner has no id
111	     */
112	    default String selfLink(Owner owner) {
113	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
114	    }
115	
116	    /**
117	     * Derives an owner's salutation from its optional title and last name: {@code "<title> <lastName>"}
118	     * when a non-blank title is present, or just the last name when no title was supplied.
119	     *
120	     * @param owner the owner to derive the salutation for
121	     * @return the composed salutation
122	     */
123	    default String salutation(Owner owner) {
124	        String title = owner.getTitle();
125	        String lastName = owner.getLastName();
126	        if (title == null || title.isBlank()) {
127	            return lastName;
128	        }
129	        return title + " " + lastName;
130	    }
131	
132	    /**
133	     * Derives an owner's age band from its birth date, computed as the owner's age on its
134	     * {@link Owner#getRegistrationDate() registration date}: {@code "MINOR"} when under {@code 18},
135	     * {@code "ADULT"} when {@code 18} to {@code 64}, and {@code "SENIOR"} when {@code 65} or older.
136	     * Returns {@code null} when the owner has no birth date, so the field is omitted from the
137	     * response.
138	     *
139	     * @param owner the owner to derive the age band for
140	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
141	     *     is held
142	     */
143	    default String ageBand(Owner owner) {
144	        java.time.LocalDate birthDate = owner.getBirthDate();
145	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
146	        if (birthDate == null || registrationDate == null) {
147	            return null;
148	        }
149	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
150	        if (age < 18) {
151	            return "MINOR";
152	        }
153	        return age < 65 ? "ADULT" : "SENIOR";
154	    }
155	
156	    /**
157	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
158	     * email, otherwise {@code "PHONE"}.
159	     *
160	     * @param owner the owner to derive the contact preference for
161	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
162	     */
163	    default String contactPreference(Owner owner) {
164	        String email = owner.getEmail();
165	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
166	    }
167	
168	    /**
169	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
170	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
171	     * normalizing telephones into E.164 form.
172	     */
173	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
174	
175	    /**
176	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
177	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
178	     * The country code is taken as the longest recognized prefix (see
179	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
180	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
181	     * is returned unchanged.
182	     *
183	     * @param owner the owner to format the telephone display for
184	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
185	     *     digit string
186	     */
187	    default String telephoneDisplay(Owner owner) {
188	        String telephone = owner.getTelephone();
189	        if (telephone == null || !telephone.startsWith("+")) {
190	            return telephone;
191	        }
192	        String digits = telephone.substring(1);
193	        if (!digits.matches("[0-9]+")) {
194	            return telephone;
195	        }
196	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
197	            .filter(digits::startsWith)
198	            .max(java.util.Comparator.comparingInt(String::length))
199	            .orElseGet(() -> digits.substring(0, 1));
200	        String national = digits.substring(countryCode.length());
201	        StringBuilder sb = new StringBuilder("+").append(countryCode);
202	        for (int i = 0; i < national.length(); i += 3) {
203	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
204	        }
205	        return sb.toString();
206	    }
207	
208	    /**
209	     * Derives an owner's locality from the unified member id: the leading {@code <REGION>} segment
210	     * of the owner's {@code memberId}, i.e. the run of letters before the 2-digit fiscal year that
211	     * follows it. Because the member id's region is itself derived from the postcode (falling back
212	     * to the city), the locality moves with the identity rather than being computed independently.
213	     * The result is {@code "UNKNOWN"} when no member id is present.
214	     *
215	     * @param owner the owner to derive the locality for
216	     * @return the region segment of the member id, or {@code "UNKNOWN"}
217	     */
218	    default String locality(Owner owner) {
219	        String memberId = owner.getMemberId();
220	        if (memberId == null || memberId.isEmpty()) {
221	            return "UNKNOWN";
222	        }
223	        int i = 0;
224	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
225	            i++;
226	        }
227	        return i == 0 ? "UNKNOWN" : memberId.substring(0, i);
228	    }
229	
230	    /**
231	     * Fixed region-to-timezone table mapping a canonical region to its IANA timezone name:
232	     * {@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}.
233	     */
234	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
235	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
236	
237	    /**
238	     * The regions considered {@code METRO} for the purposes of {@link #ownerSegment(Owner)}: the
239	     * known regions {@code NSW}, {@code VIC} and {@code QLD}. Any other locality is {@code REGIONAL}.
240	     */
241	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
242	
243	    /**
244	     * Derives an owner's segment, formatted {@code <TIER>_<AREA>}. {@code TIER} is {@code PREMIUM}
245	     * when the owner's {@link #membershipLevel(Owner) membership level} is {@code 3} or more,
246	     * otherwise {@code STANDARD}. {@code AREA} is {@code METRO} when the owner's
247	     * {@link #locality(Owner) locality} is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
248	     * otherwise {@code REGIONAL}. The result is one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
249	     * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
250	     *
251	     * @param owner the owner to derive the segment for
252	     * @return the {@code <TIER>_<AREA>} owner segment
253	     */
254	    default String ownerSegment(Owner owner) {
255	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
256	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
257	        return tier + "_" + area;
258	    }
259	
260	    /**
261	     * Derives an owner's IANA timezone name from its {@link #locality(Owner) locality/region} using
262	     * the fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
263	     * {@code QLD->Australia/Brisbane}). Returns {@code null} when the region has no known timezone, so
264	     * the field is omitted from the response.
265	     *
266	     * @param owner the owner to derive the timezone for
267	     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
268	     */
269	    default String timezone(Owner owner) {
270	        return REGION_TIMEZONES.get(locality(owner));
271	    }
272	
273	    /**
274	     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
275	     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
276	     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
277	     * than one elapsed fiscal year - the number of fiscal years between the owner's registration
278	     * date and the current server date (the fiscal year starts on 1 July). Because a newly created
279	     * owner registers on the current date, its tenure is zero, so a new owner never earns the tenure
280	     * points.
281	     *
282	     * @param owner the owner to derive the membership points for
283	     * @return the membership points, {@code 0} or more
284	     */
285	    default Integer membershipPoints(Owner owner) {
286	        return membershipPoints(owner, owner.getHouseholdMemberCount());
287	    }
288	
289	    /**
290	     * Derives an owner's membership points as {@link #membershipPoints(Owner)}, but scoring the
291	     * household bonus against the supplied household member count rather than the owner's stored one.
292	     * Used to evaluate an existing household member's current standing against the household size that
293	     * includes a newly joining owner.
294	     *
295	     * @param owner the owner to derive the membership points for
296	     * @param householdMemberCount the household member count to score the household bonus against
297	     * @return the membership points, {@code 0} or more
298	     */
299	    private int membershipPoints(Owner owner, Integer householdMemberCount) {
300	        int points = 0;
301	        String email = owner.getEmail();
302	        if (email != null && !email.isBlank()) {
303	            points += 2;
304	        }
305	        Integer namesakeCount = owner.getNamesakeCount();
306	        if (namesakeCount != null && namesakeCount == 0) {
307	            points += 1;
308	        }
309	        if (householdMemberCount != null && householdMemberCount >= 3) {
310	            points += 2;
311	        }
312	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
313	        long tenureFiscalYears = registrationDate == null ? 0
314	            : fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate);
315	        if (tenureFiscalYears > 1) {
316	            points += 3;
317	        }
318	        return points;
319	    }
320	
321	    /**
322	     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
323	     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
324	     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more. The points-derived
325	     * level is then capped by the owner's {@link Owner#getMembershipLevelCap() membership level cap}
326	     * when one was recorded at creation - a new owner's level can never exceed one above the highest
327	     * level among the household members that already existed. When no cap was recorded (the owner had
328	     * no existing household member) the points-derived level is returned unchanged.
329	     *
330	     * @param owner the owner to derive the membership level for
331	     * @return the membership level, between {@code 1} and {@code 4}
332	     */
333	    default Integer membershipLevel(Owner owner) {
334	        return cappedLevel(owner, levelForPoints(membershipPoints(owner)));
335	    }
336	
337	    /**
338	     * Derives an existing household member's current membership level as it would stand in a household
339	     * of the supplied size, so a newly joining owner's level ceiling can be measured against the
340	     * up-to-date standing of the members it joins. The member's own {@link Owner#getMembershipLevelCap()
341	     * cap} still applies.
342	     *
343	     * @param owner the existing household member to evaluate
344	     * @param householdMemberCount the household member count that includes the joining owner
345	     * @return the member's capped membership level for that household size, between {@code 1} and {@code 4}
346	     */
347	    default Integer householdMemberLevel(Owner owner, int householdMemberCount) {
348	        return cappedLevel(owner, levelForPoints(membershipPoints(owner, householdMemberCount)));
349	    }
350	
351	    /**
352	     * Applies an owner's {@link Owner#getMembershipLevelCap() membership level cap} to a points-derived
353	     * level: the level is returned unchanged when no cap was recorded, otherwise it is clamped to the
354	     * cap.
355	     *
356	     * @param owner the owner whose cap is applied
357	     * @param level the uncapped points-derived level
358	     * @return the capped level
359	     */
360	    private Integer cappedLevel(Owner owner, int level) {
361	        Integer cap = owner.getMembershipLevelCap();
362	        if (cap != null && level > cap) {
363	            return cap;
364	        }
365	        return level;
366	    }
367	
368	    /**
369	     * Maps membership points to a numeric level: level {@code 1} for {@code 0}-{@code 1} points,
370	     * {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}, and {@code 4} for
371	     * {@code 6} or more.
372	     *
373	     * @param points the membership points
374	     * @return the points-based membership level, between {@code 1} and {@code 4}
375	     */
376	    private Integer levelForPoints(int points) {
377	        if (points <= 1) {
378	            return 1;
379	        }
380	        if (points <= 3) {
381	            return 2;
382	        }
383	        if (points <= 5) {
384	            return 3;
385	        }
386	        return 4;
387	    }
388	
389	    /**
390	     * Derives an owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two
391	     * digits (zero-padded) of the fiscal year that the owner's business-day-adjusted registration
392	     * date falls in. The fiscal year starts on 1 July and is labelled by the calendar year in which
393	     * it ends, so a registration date on or after 1 July belongs to the next year's fiscal year
394	     * (e.g. {@code 2026-08-11 -> FY27}, {@code 2026-01-05 -> FY26}).
395	     *
396	     * @param owner the owner to derive the fiscal year for
397	     * @return the formatted fiscal year
398	     */
399	    default String fiscalYear(Owner owner) {
400	        return String.format("FY%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
401	    }
402	
403	    /**
404	     * Computes the fiscal year a date falls in as a full four-digit year. The fiscal year starts on
405	     * 1 July and is labelled by the calendar year in which it ends, so a date in July through
406	     * December belongs to the following calendar year's fiscal year and a date in January through
407	     * June belongs to its own calendar year's fiscal year.
408	     *
409	     * @param date the date to compute the fiscal year for
410	     * @return the fiscal year as a four-digit calendar year
411	     */
412	    private int fiscalYearValue(java.time.LocalDate date) {
413	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
414	    }
415	
416	    /**
417	     * Derives an owner's household identifier: the first 12 hex characters of the SHA-256 digest
418	     * over {@code <normalizedLastName>|<postcode>}, where the last name is normalized
419	     * case-insensitively with collapsed whitespace and a missing postcode contributes the empty
420	     * string. Because it is derived deterministically from the last name and postcode, every owner
421	     * that shares those two fields receives the same value - including owners created via the
422	     * {@code sharesHousehold} flag, which by definition have a matching last name and postcode.
423	     *
424	     * @param owner the owner to derive the household identifier for
425	     * @return the 12 upper-case hex character household identifier, never blank
426	     */
427	    default String householdId(Owner owner) {
428	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
429	        String key = normalizeHouseholdField(owner.getLastName()) + '|' + postcode;
430	        try {
431	            byte[] digest = MessageDigest.getInstance("SHA-256")
432	                .digest(key.getBytes(StandardCharsets.UTF_8));
433	            StringBuilder sb = new StringBuilder(12);
434	            for (int i = 0; i < 6; i++) {
435	                sb.append(String.format("%02X", digest[i]));
436	            }
437	            return sb.toString();
438	        }
439	        catch (NoSuchAlgorithmException ex) {
440	            throw new IllegalStateException("SHA-256 not available", ex);
441	        }
442	    }
443	
444	    /**
445	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
446	     * is the full lower-case hex SHA-256 digest over
447	     * {@code <normalizedTelephone>|<email or empty>|<soundex(lastName)>}: the owner's (already E.164
448	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
449	     * and the {@link Soundex Soundex} code of its last name. Two owners are duplicates only when
450	     * their whole identity keys are equal; because the telephone is part of the key, owners sharing a
451	     * surname (same soundex) but holding different telephones have different keys.
452	     *
453	     * @param owner the owner to derive the identity key for
454	     * @return the 64-character lower-case hex identity key
455	     */
456	    default String identityKey(Owner owner) {
457	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
458	        String email = owner.getEmail() == null ? "" : owner.getEmail();
459	        String key = telephone + '|' + email + '|' + Soundex.encode(owner.getLastName());
460	        try {
461	            byte[] digest = MessageDigest.getInstance("SHA-256")
462	                .digest(key.getBytes(StandardCharsets.UTF_8));
463	            StringBuilder sb = new StringBuilder(digest.length * 2);
464	            for (byte b : digest) {
465	                sb.append(String.format("%02x", b));
466	            }
467	            return sb.toString();
468	        }
469	        catch (NoSuchAlgorithmException ex) {
470	            throw new IllegalStateException("SHA-256 not available", ex);
471	        }
472	    }
473	
474	    /**
475	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
476	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
477	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
478	     *
479	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
480	     * conversion and apply it to unrelated String properties (last name, address, ...).
481	     */
482	    private String normalizeHouseholdField(String value) {
483	        if (value == null) {
484	            return "";
485	        }
486	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
487	    }
488	
489	    Owner toOwner(OwnerDto ownerDto);
490	
491	    @Mapping(target = "id", ignore = true)
492	    @Mapping(target = "pets", ignore = true)
493	    Owner toOwner(OwnerFieldsDto ownerDto);
494	
495	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
496	
497	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
498	
499	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
500	        OwnerPageDto ownerPageDto = new OwnerPageDto();
501	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
502	        ownerPageDto.setPage(ownerPage.getNumber());
503	        ownerPageDto.setSize(ownerPage.getSize());
504	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
505	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
506	        return ownerPageDto;
507	    }
508	}
