		return sha256hex(s).substring(0, n).toUpperCase();
	}

	/** Luhn check digit (0-9) over the digits contained in {@code s}. */
	protected static int luhn(String s) {
		int sum = 0;
		boolean dbl = true;
		for (int i = s.length() - 1; i >= 0; i--) {
			char c = s.charAt(i);
			if (c < '0' || c > '9') {
				continue;
			}
			int d = c - '0';
			if (dbl) {
				d *= 2;
				if (d > 9) {
					d -= 9;
				}
			}
			sum += d;
			dbl = !dbl;
		}
		return (10 - (sum % 10)) % 10;
	}
}

