package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.util.Soundex;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Collection;
import java.util.List;
import java.util.Locale;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
    @Mapping(target = "salutation", expression = "java(salutation(owner))")
    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
    @Mapping(target = "apiVersion", expression = "java(apiVersion())")
    @Mapping(target = "identity", expression = "java(identity(owner))")
    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "timezone", expression = "java(timezone(owner))")
    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
    OwnerDto toOwnerDto(Owner owner);

    /**
     * The fixed version tag mixed into every version-2 owner identifier (the memberId, householdId and
     * identityKey). Because it participates in each identifier's derivation, every value produced under
     * version 2 differs from the value the same owner would have produced under version 1, and no
     * version-1 value recurs. The tag is deliberately confined to the identifiers: it never appears in
     * the user-facing {@code locality} or {@code timezone}, nor in the region the owner segment derives
     * from, all of which continue to use the plain region code.
     */
    String IDENTITY_VERSION_TAG = "V2";

    /**
     * The owner identity contract version carried by the top-level {@code apiVersion} field: {@code 2},
     * signalling the version-2 identity in which the identifiers are grouped under {@code identity} and
     * rederived with the {@link #IDENTITY_VERSION_TAG}.
     *
     * @return the fixed API version, {@code 2}
     */
    default Integer apiVersion() {
        return 2;
    }

    /**
     * Groups the owner's version-2 identifiers - the {@code memberId} (assigned at creation and stored
     * on the owner), the {@link #householdId(Owner) householdId} and the {@link #identityKey(Owner)
     * identityKey} - under the nested {@code identity} object of the owner response. Each identifier is
     * rederived with the fixed {@link #IDENTITY_VERSION_TAG}.
     *
     * @param owner the owner to build the identity object for
     * @return the populated identity object
     */
    default OwnerIdentityDto identity(Owner owner) {
        OwnerIdentityDto identity = new OwnerIdentityDto();
        identity.setMemberId(owner.getMemberId());
        identity.setHouseholdId(householdId(owner));
        identity.setIdentityKey(identityKey(owner));
        return identity;
    }

    /**
     * Known disposable email service names, matched as a whole dot-separated label anywhere in an
     * owner's email domain to detect a domain that is <em>disposable-adjacent</em>. These are the base
     * labels of the disposable domains rejected outright at creation ({@code mailinator.com},
     * {@code tempmail.com}, {@code guerrillamail.com}); a domain that carries one of these labels but
     * is not itself on the exact blocklist (a subdomain such as {@code mail.mailinator.com} or a
     * different TLD such as {@code tempmail.net}) evaded the blocklist yet is still risky.
     */
    java.util.Set<String> DISPOSABLE_ADJACENT_LABELS = java.util.Set.of(
        "mailinator", "tempmail", "guerrillamail");

    /**
     * Derives an owner's risk flag: {@code true} when any of the following hold, otherwise
     * {@code false}. The owner is a possible duplicate ({@link Owner#getPossibleDuplicate()}), the
     * owner's email domain is {@link #disposableAdjacentEmail(Owner) disposable-adjacent}, or the
     * owner's city was over its soft capacity when created ({@link Owner#getCapacityWarning()}).
     *
     * @param owner the owner to derive the risk flag for
     * @return {@code true} when the owner is a possible duplicate, has a disposable-adjacent email
     *     domain, or was created over its city's soft capacity; otherwise {@code false}
     */
    default Boolean riskFlag(Owner owner) {
        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
            || Boolean.TRUE.equals(owner.getCapacityWarning())
            || disposableAdjacentEmail(owner);
    }

    /**
     * Determines whether an owner's email domain is <em>disposable-adjacent</em>: any of the domain's
     * dot-separated labels (compared case-insensitively) matches a known disposable email service name
     * ({@link #DISPOSABLE_ADJACENT_LABELS}). This catches domains that evade the exact disposable
     * blocklist enforced at creation, such as a subdomain ({@code mail.mailinator.com}) or a variant
     * TLD ({@code tempmail.net}). An owner with no email, or a value without a domain part, is not
     * disposable-adjacent.
     *
     * @param owner the owner whose email domain is examined
     * @return {@code true} when the email domain carries a known disposable-service label, otherwise
     *     {@code false}
     */
    default boolean disposableAdjacentEmail(Owner owner) {
        String email = owner.getEmail();
        if (email == null || email.isBlank()) {
            return false;
        }
        int at = email.lastIndexOf('@');
        if (at < 0 || at == email.length() - 1) {
            return false;
        }
        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
        for (String label : domain.split("\\.")) {
            if (DISPOSABLE_ADJACENT_LABELS.contains(label)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Derives a link to the owner's own resource, formatted {@code /api/owners/<id>} where
     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet, so the
     * field is omitted from the response.
     *
     * @param owner the owner to derive the self link for
     * @return the {@code /api/owners/<id>} self link, or {@code null} when the owner has no id
     */
    default String selfLink(Owner owner) {
        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
    }

    /**
     * Derives an owner's salutation from its optional title and last name: {@code "<title> <lastName>"}
     * when a non-blank title is present, or just the last name when no title was supplied.
     *
     * @param owner the owner to derive the salutation for
     * @return the composed salutation
     */
    default String salutation(Owner owner) {
        String title = owner.getTitle();
        String lastName = owner.getLastName();
        if (title == null || title.isBlank()) {
            return lastName;
        }
        return title + " " + lastName;
    }

    /**
     * Derives an owner's age band from its birth date, computed as the owner's age on its
     * {@link Owner#getRegistrationDate() registration date}: {@code "MINOR"} when under {@code 18},
     * {@code "ADULT"} when {@code 18} to {@code 64}, and {@code "SENIOR"} when {@code 65} or older.
     * Returns {@code null} when the owner has no birth date, so the field is omitted from the
     * response.
     *
     * @param owner the owner to derive the age band for
     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
     *     is held
     */
    default String ageBand(Owner owner) {
        java.time.LocalDate birthDate = owner.getBirthDate();
        java.time.LocalDate registrationDate = owner.getRegistrationDate();
        if (birthDate == null || registrationDate == null) {
            return null;
        }
        int age = java.time.Period.between(birthDate, registrationDate).getYears();
        if (age < 18) {
            return "MINOR";
        }
        return age < 65 ? "ADULT" : "SENIOR";
    }

    /**
     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
     * email, otherwise {@code "PHONE"}.
     *
     * @param owner the owner to derive the contact preference for
     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
     */
    default String contactPreference(Owner owner) {
        String email = owner.getEmail();
        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
    }

    /**
     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
     * normalizing telephones into E.164 form.
     */
    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");

    /**
     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
     * The country code is taken as the longest recognized prefix (see
     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
     * is returned unchanged.
     *
     * @param owner the owner to format the telephone display for
     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
     *     digit string
     */
    default String telephoneDisplay(Owner owner) {
        String telephone = owner.getTelephone();
        if (telephone == null || !telephone.startsWith("+")) {
            return telephone;
        }
        String digits = telephone.substring(1);
        if (!digits.matches("[0-9]+")) {
            return telephone;
        }
        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
            .filter(digits::startsWith)
            .max(java.util.Comparator.comparingInt(String::length))
            .orElseGet(() -> digits.substring(0, 1));
        String national = digits.substring(countryCode.length());
        StringBuilder sb = new StringBuilder("+").append(countryCode);
        for (int i = 0; i < national.length(); i += 3) {
            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
        }
        return sb.toString();
    }

    /**
     * Fixed region-to-inclusive-4-digit-postcode-range table: {@code NSW 2000-2099}, {@code VIC
     * 3000-3099}, {@code QLD 4000-4099}. Mirrors the canonical ranges used to derive an owner's region
     * from its postcode.
     */
    java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    /**
     * Derives an owner's plain region code, preferring the postcode over the city. The postcode is
     * looked up against the canonical region ranges first ({@code NSW 2000-2099}, {@code VIC
     * 3000-3099}, {@code QLD 4000-4099}); only when the postcode is absent or in no known range does
     * the derivation fall back to the fixed city-to-region table ({@code Sydney->NSW},
     * {@code Melbourne->VIC}, {@code Brisbane->QLD}). The result is {@code "UNKNOWN"} when neither the
     * postcode nor the city resolves to a region. This is the plain region used for the user-facing
     * {@code locality}, {@code timezone} and the owner segment - it never carries the
     * {@link #IDENTITY_VERSION_TAG}, which is confined to the identifiers.
     *
     * @param owner the owner to derive the region for
     * @return the region code {@code NSW}, {@code VIC}, {@code QLD} or {@code UNKNOWN}
     */
    default String region(Owner owner) {
        String fromPostcode = regionFromPostcode(owner.getPostcode());
        if (fromPostcode != null) {
            return fromPostcode;
        }
        return regionFromCity(owner.getCity());
    }

    private String regionFromPostcode(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    private String regionFromCity(String city) {
        if (city == null) {
            return "UNKNOWN";
        }
        return switch (city) {
            case "Sydney" -> "NSW";
            case "Melbourne" -> "VIC";
            case "Brisbane" -> "QLD";
            default -> "UNKNOWN";
        };
    }

    /**
     * Derives an owner's locality: the plain {@link #region(Owner) region code} derived from the
     * owner's postcode (falling back to the city). The locality is <em>not</em> an identifier, so it
     * remains the plain region (for example {@code "NSW"}) and never carries the version-2
     * {@link #IDENTITY_VERSION_TAG}. The result is {@code "UNKNOWN"} when no region resolves.
     *
     * @param owner the owner to derive the locality for
     * @return the plain region code, or {@code "UNKNOWN"}
     */
    default String locality(Owner owner) {
        return region(owner);
    }

    /**
     * Fixed region-to-timezone table mapping a canonical region to its IANA timezone name:
     * {@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}.
     */
    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");

    /**
     * The regions considered {@code METRO} for the purposes of {@link #ownerSegment(Owner)}: the
     * known regions {@code NSW}, {@code VIC} and {@code QLD}. Any other locality is {@code REGIONAL}.
     */
    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");

    /**
     * Derives an owner's segment, formatted {@code <TIER>_<AREA>}. {@code TIER} is {@code PREMIUM}
     * when the owner's {@link #membershipLevel(Owner) membership level} is {@code 3} or more,
     * otherwise {@code STANDARD}. {@code AREA} is {@code METRO} when the owner's
     * {@link #locality(Owner) locality} is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
     * otherwise {@code REGIONAL}. The result is one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
     * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
     *
     * @param owner the owner to derive the segment for
     * @return the {@code <TIER>_<AREA>} owner segment
     */
    default String ownerSegment(Owner owner) {
        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
        return tier + "_" + area;
    }

    /**
     * Derives an owner's IANA timezone name from its {@link #locality(Owner) locality/region} using
     * the fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
     * {@code QLD->Australia/Brisbane}). Returns {@code null} when the region has no known timezone, so
     * the field is omitted from the response.
     *
     * @param owner the owner to derive the timezone for
     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
     */
    default String timezone(Owner owner) {
        return REGION_TIMEZONES.get(locality(owner));
    }

    /**
     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
     * than one elapsed fiscal year - the number of fiscal years between the owner's registration
     * date and the current server date (the fiscal year starts on 1 July). Because a newly created
     * owner registers on the current date, its tenure is zero, so a new owner never earns the tenure
     * points.
     *
     * @param owner the owner to derive the membership points for
     * @return the membership points, {@code 0} or more
     */
    default Integer membershipPoints(Owner owner) {
        return membershipPoints(owner, owner.getHouseholdMemberCount());
    }

    /**
     * Derives an owner's membership points as {@link #membershipPoints(Owner)}, but scoring the
     * household bonus against the supplied household member count rather than the owner's stored one.
     * Used to evaluate an existing household member's current standing against the household size that
     * includes a newly joining owner.
     *
     * @param owner the owner to derive the membership points for
     * @param householdMemberCount the household member count to score the household bonus against
     * @return the membership points, {@code 0} or more
     */
    private int membershipPoints(Owner owner, Integer householdMemberCount) {
        int points = 0;
        String email = owner.getEmail();
        if (email != null && !email.isBlank()) {
            points += 2;
        }
        Integer namesakeCount = owner.getNamesakeCount();
        if (namesakeCount != null && namesakeCount == 0) {
            points += 1;
        }
        if (householdMemberCount != null && householdMemberCount >= 3) {
            points += 2;
        }
        java.time.LocalDate registrationDate = owner.getRegistrationDate();
        long tenureFiscalYears = registrationDate == null ? 0
            : fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate);
        if (tenureFiscalYears > 1) {
            points += 3;
        }
        return points;
    }

    /**
     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more. The points-derived
     * level is then capped by the owner's {@link Owner#getMembershipLevelCap() membership level cap}
     * when one was recorded at creation - a new owner's level can never exceed one above the highest
     * level among the household members that already existed. When no cap was recorded (the owner had
     * no existing household member) the points-derived level is returned unchanged.
     *
     * @param owner the owner to derive the membership level for
     * @return the membership level, between {@code 1} and {@code 4}
     */
    default Integer membershipLevel(Owner owner) {
        return cappedLevel(owner, levelForPoints(membershipPoints(owner)));
    }

    /**
     * Derives an existing household member's current membership level as it would stand in a household
     * of the supplied size, so a newly joining owner's level ceiling can be measured against the
     * up-to-date standing of the members it joins. The member's own {@link Owner#getMembershipLevelCap()
     * cap} still applies.
     *
     * @param owner the existing household member to evaluate
     * @param householdMemberCount the household member count that includes the joining owner
     * @return the member's capped membership level for that household size, between {@code 1} and {@code 4}
     */
    default Integer householdMemberLevel(Owner owner, int householdMemberCount) {
        return cappedLevel(owner, levelForPoints(membershipPoints(owner, householdMemberCount)));
    }

    /**
     * Applies an owner's {@link Owner#getMembershipLevelCap() membership level cap} to a points-derived
     * level: the level is returned unchanged when no cap was recorded, otherwise it is clamped to the
     * cap.
     *
     * @param owner the owner whose cap is applied
     * @param level the uncapped points-derived level
     * @return the capped level
     */
    private Integer cappedLevel(Owner owner, int level) {
        Integer cap = owner.getMembershipLevelCap();
        if (cap != null && level > cap) {
            return cap;
        }
        return level;
    }

    /**
     * Maps membership points to a numeric level: level {@code 1} for {@code 0}-{@code 1} points,
     * {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}, and {@code 4} for
     * {@code 6} or more.
     *
     * @param points the membership points
     * @return the points-based membership level, between {@code 1} and {@code 4}
     */
    private Integer levelForPoints(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    /**
     * Derives an owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two
     * digits (zero-padded) of the fiscal year that the owner's business-day-adjusted registration
     * date falls in. The fiscal year starts on 1 July and is labelled by the calendar year in which
     * it ends, so a registration date on or after 1 July belongs to the next year's fiscal year
     * (e.g. {@code 2026-08-11 -> FY27}, {@code 2026-01-05 -> FY26}).
     *
     * @param owner the owner to derive the fiscal year for
     * @return the formatted fiscal year
     */
    default String fiscalYear(Owner owner) {
        return String.format("FY%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
    }

    /**
     * Computes the fiscal year a date falls in as a full four-digit year. The fiscal year starts on
     * 1 July and is labelled by the calendar year in which it ends, so a date in July through
     * December belongs to the following calendar year's fiscal year and a date in January through
     * June belongs to its own calendar year's fiscal year.
     *
     * @param date the date to compute the fiscal year for
     * @return the fiscal year as a four-digit calendar year
     */
    private int fiscalYearValue(java.time.LocalDate date) {
        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
    }

    /**
     * Derives an owner's household identifier: the first 12 hex characters of the SHA-256 digest
     * over {@code <normalizedLastName>|<postcode>}, where the last name is normalized
     * case-insensitively with collapsed whitespace and a missing postcode contributes the empty
     * string. Because it is derived deterministically from the last name and postcode, every owner
     * that shares those two fields receives the same value - including owners created via the
     * {@code sharesHousehold} flag, which by definition have a matching last name and postcode.
     *
     * @param owner the owner to derive the household identifier for
     * @return the 12 upper-case hex character household identifier, never blank
     */
    default String householdId(Owner owner) {
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        String key = normalizeHouseholdField(owner.getLastName()) + '|' + postcode;
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /**
     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
     * is the full lower-case hex SHA-256 digest over
     * {@code <normalizedTelephone>|<email or empty>|<soundex(lastName)>}: the owner's (already E.164
     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
     * and the {@link Soundex Soundex} code of its last name. Two owners are duplicates only when
     * their whole identity keys are equal; because the telephone is part of the key, owners sharing a
     * surname (same soundex) but holding different telephones have different keys.
     *
     * @param owner the owner to derive the identity key for
     * @return the 64-character lower-case hex identity key
     */
    default String identityKey(Owner owner) {
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        String email = owner.getEmail() == null ? "" : owner.getEmail();
        String key = telephone + '|' + email + '|' + Soundex.encode(owner.getLastName());
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /**
     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
     *
     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
     * conversion and apply it to unrelated String properties (last name, address, ...).
     */
    private String normalizeHouseholdField(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

